            const next = [ev, ...prev];
            persistExecutionMerge({
                ...buildEmployeeAssignmentPatchForDebtorKey(
                    d,
                    targetKey,
                    {
                        ...a,
                        phase: 'investigation_pending',
                        investigationDecisionId: decisionId,
                    },
                    pk
                ),
                timelineEvents: next,
            });
            return next;
